#include <stdio.h>

int main() {
    int n = 10;
    int started = 0;
    for (int i = 31; i >= 0; i--) {
        int bit = (n >> i) & 1;
        if (bit) {
            started = 1;
        }
        if (started) {
            printf("%d", bit);
        }
    }
    printf("\n");
    return 0;
}
